  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In human PET, 18F-AZAN—a basic pyridine-containing nAChR ligand—rapidly enters the brain, showing that this chemotype achieves meaningful CNS access despite a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Epibatidine, a strongly basic chloropyridine azabicyclic amine, reaches 11.5% whole-brain ID in rodents, demonstrating that basic pyridine-containing amines can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Pyrazinamide, a small polar pyrazine with low lipophilicity, maintains CSF/plasma ratios near 1 in rabbits, showing that low logD does not preclude excellent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Clonidine, a small basic heteroaromatic, gives brain/blood ratios above 1.3 in rats and is classified as non-P-gp, supporting CNS access for small basic molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is A-85380, a known α4β2 nAChR PET ligand; high-transfer analogues with basic pyridine/azetidine motifs and small polar heteroaromatics show robust brain/CSF uptake, overriding the unfavorable passive-diffusion prior.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query in the supplied evidence; conclusion relies on close structural/functional analogues.",
    "Efflux-transporter status of the query is not directly measured, though several positive analogues are non-P-gp or passive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

